package chessrules_test

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/Bernabass/chess-detective/services/api/internal/chessrules"
)

// The cross-language vectors (SPEC §11.2), generated by the TypeScript engine:
// pnpm --filter @retrograde/engine fixtures.
type vectors struct {
	EngineVersion string `json:"engineVersion"`
	Legal         []struct {
		Moves    []string `json:"moves"`
		FinalKey string   `json:"finalKey"`
		SAN      []string `json:"san"`
	} `json:"legal"`
	Illegal []struct {
		Moves     []string `json:"moves"`
		IllegalAt int      `json:"illegalAt"`
		Kind      string   `json:"kind"`
	} `json:"illegal"`
}

func loadVectors(t *testing.T) vectors {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "..", "..", "fixtures", "replay-vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if len(v.Legal) < 500 || len(v.Illegal) < 100 {
		t.Fatalf("expected at least 500 legal and 100 illegal vectors, got %d and %d", len(v.Legal), len(v.Illegal))
	}
	return v
}

// The Go library must agree with the TypeScript engine on every vector: the same final target
// key for legal games, and an error at exactly the same ply for illegal ones.
func TestReplayMatchesEngineVectors(t *testing.T) {
	v := loadVectors(t)
	for i, g := range v.Legal {
		res, err := chessrules.Replay(g.Moves)
		if err != nil {
			t.Errorf("legal[%d]: unexpected error %v", i, err)
			continue
		}
		if res.TargetKey != g.FinalKey {
			t.Errorf("legal[%d]: target key %q, want %q", i, res.TargetKey, g.FinalKey)
		}
		if len(res.Moves) != len(g.Moves) || len(g.SAN) != len(g.Moves) {
			t.Errorf("legal[%d]: %d moves described and %d SAN in the vector, want %d", i, len(res.Moves), len(g.SAN), len(g.Moves))
			continue
		}
		// Hint 3 shows SAN from this library; the web app writes SAN with the engine.
		for j, m := range res.Moves {
			if m.SAN != g.SAN[j] {
				t.Errorf("legal[%d] ply %d (%s): SAN %q, engine says %q", i, j, m.UCI, m.SAN, g.SAN[j])
				break
			}
		}
	}
	kinds := map[string]int{}
	for i, g := range v.Illegal {
		kinds[g.Kind]++
		_, err := chessrules.Replay(g.Moves)
		var illegal *chessrules.IllegalMoveError
		if !errors.As(err, &illegal) {
			t.Errorf("illegal[%d] (%s): got %v, want an IllegalMoveError at ply %d", i, g.Kind, err, g.IllegalAt)
			continue
		}
		if illegal.Ply != g.IllegalAt {
			t.Errorf("illegal[%d] (%s, %s): error at ply %d, want %d", i, g.Kind, g.Moves[g.IllegalAt], illegal.Ply, g.IllegalAt)
		}
	}
	t.Logf("checked %d legal and %d illegal games (engine %s), illegal kinds %v",
		len(v.Legal), len(v.Illegal), v.EngineVersion, kinds)
}

func TestReplayDescribesMoves(t *testing.T) {
	// 1.e4 d5 2.exd5 Qxd5 3.Nc3 Qa5 4.Nf3 Nf6 5.Bc4 Bf5 6.O-O: SAN, pieces, captures, castling.
	res, err := chessrules.Replay([]string{
		"e2e4", "d7d5", "e4d5", "d8d5", "b1c3", "d5a5", "g1f3", "g8f6", "f1c4", "c8f5", "e1g1",
	})
	if err != nil {
		t.Fatal(err)
	}
	want := []struct {
		san     string
		piece   chessrules.Piece
		white   bool
		capture bool
	}{
		{"e4", chessrules.Pawn, true, false},
		{"d5", chessrules.Pawn, false, false},
		{"exd5", chessrules.Pawn, true, true},
		{"Qxd5", chessrules.Queen, false, true},
		{"Nc3", chessrules.Knight, true, false},
		{"Qa5", chessrules.Queen, false, false},
		{"Nf3", chessrules.Knight, true, false},
		{"Nf6", chessrules.Knight, false, false},
		{"Bc4", chessrules.Bishop, true, false},
		{"Bf5", chessrules.Bishop, false, false},
		{"O-O", chessrules.King, true, false},
	}
	for i, w := range want {
		m := res.Moves[i]
		if m.SAN != w.san || m.Piece != w.piece || m.White != w.white || m.Capture != w.capture {
			t.Errorf("move %d = %+v, want SAN %s piece %v white %v capture %v", i, m, w.san, w.piece, w.white, w.capture)
		}
	}
	if res.TargetKey != "rn2kb1r/ppp1pppp/5n2/q4b2/2B5/2N2N2/PPPP1PPP/R1BQ1RK1 b" {
		t.Errorf("target key = %q", res.TargetKey)
	}
}

func TestReplayRejectsMalformedAndMissingOrNeedlessPromotions(t *testing.T) {
	cases := []struct {
		name  string
		moves []string
		ply   int
	}{
		{"not UCI", []string{"e4"}, 0},
		{"uppercase", []string{"E2E4"}, 0},
		{"needless promotion letter", []string{"e2e4q"}, 0},
		{"bad promotion letter", []string{"e2e4k"}, 0},
		{"no piece on the square", []string{"e3e4"}, 0},
		{"wrong side's piece", []string{"e7e5"}, 0},
		// White's a-pawn reaches a7 and takes b8 without saying what it promotes to.
		{"missing promotion letter", []string{"a2a4", "b7b5", "a4b5", "a7a6", "b5a6", "c8b7", "a6b7", "h7h6", "b7a8"}, 8},
	}
	for _, c := range cases {
		_, err := chessrules.Replay(c.moves)
		var illegal *chessrules.IllegalMoveError
		if !errors.As(err, &illegal) || illegal.Ply != c.ply {
			t.Errorf("%s: got %v, want an IllegalMoveError at ply %d", c.name, err, c.ply)
		}
	}
	// The same promotion with its letter is fine.
	if _, err := chessrules.Replay([]string{"a2a4", "b7b5", "a4b5", "a7a6", "b5a6", "c8b7", "a6b7", "h7h6", "b7a8n"}); err != nil {
		t.Errorf("underpromotion with capture: %v", err)
	}
}

func TestReplayIgnoresDrawRules(t *testing.T) {
	// Knights out and back five times: a fivefold repetition, which the engine (and the daily
	// puzzle) ignores. The library's Game would end the game; Replay must keep going.
	var moves []string
	for range 6 {
		moves = append(moves, "g1f3", "g8f6", "f3g1", "f6g8")
	}
	moves = append(moves, "e2e4")
	res, err := chessrules.Replay(moves)
	if err != nil {
		t.Fatal(err)
	}
	if res.TargetKey != "rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b" {
		t.Errorf("target key = %q", res.TargetKey)
	}
}
